{
  "reviewer": "Reviewer - No Persona",
  "decision": "Reject",
  "scores": {
    "novelty": 3,
    "soundness": 4,
    "significance": 4,
    "evaluation": 4,
    "clarity": 4
  },
  "strengths": [
    "Systematic investigation of inference scaling for long-context RAG with comprehensive experiments across multiple benchmark datasets",
    "Introduction of two novel scaling strategies (DRAG and IterDRAG) that effectively utilize test-time computation",
    "Development of a computation allocation model that predicts optimal configurations and shows strong generalization capabilities"
  ],
  "weaknesses": [
    "Limited comparison to state-of-the-art baselines beyond standard RAG and QA methods",
    "Insufficient analysis of computational costs and practical deployment considerations"
  ],
  "weakness_details": [
    {
      "weakness": "Limited comparison to state-of-the-art baselines beyond standard RAG and QA methods",
      "severity": "major",
      "evidence": "The paper compares against zero-shot QA, many-shot QA, and standard RAG, but does not include comparisons to recent state-of-the-art RAG methods like Active RAG (Jiang et al., 2023) or In-Context RALM (Ram et al., 2023) mentioned in the related work",
      "affected_claim": "Claims of state-of-the-art performance and superior scaling properties",
      "fixable_without_substantial_new_work": true
    },
    {
      "weakness": "Insufficient analysis of computational costs and practical deployment considerations",
      "severity": "minor",
      "evidence": "While the paper focuses on effective context length as a proxy for computation, it does not provide detailed analysis of actual inference time, latency, or resource requirements, which are critical for real-world deployment",
      "affected_claim": "Practical guidance for optimal computation allocation",
      "fixable_without_substantial_new_work": true
    }
  ],
  "acceptance_gates": {
    "soundness": {
      "result": "pass",
      "justification": "The central claims are technically supported through extensive experiments, rigorous evaluation metrics, and statistical analysis of the computation allocation model"
    },
    "novelty": {
      "result": "fail",
      "justification": "The rebuttal acknowledges that direct comparisons to SOTA baselines are absent and clarifies the core contribution as scaling laws. This confirms the submitted work builds upon established concepts (in-context learning, iterative retrieval) rather than introducing a fundamentally novel methodology. The novelty remains incremental."
    },
    "significance": {
      "result": "pass",
      "justification": "The work provides meaningful insights into optimizing test-time computation for RAG, with demonstrated gains up to 58.9% on benchmarks, which advances the field of efficient LLM deployment"
    },
    "evaluation": {
      "result": "pass",
      "justification": "Experiments are comprehensive across multiple datasets and metrics, with careful ablation studies and validation of the computation allocation model"
    },
    "presentation": {
      "result": "pass",
      "justification": "The paper is well-structured, clearly written, and includes sufficient details for reproducibility and assessment"
    }
  ],
  "summary_comment": "The authors' rebuttal acknowledges the limitations regarding baseline comparisons and agrees to refine the claims. However, the evaluation is of the submitted paper, not promised revisions. The lack of comparison to contemporary RAG methods remains a major weakness that undermines the claim of superior scaling properties and state-of-the-art performance. The core contributions—inference scaling laws and a computation allocation model—are built upon established paradigms, limiting the novelty for a top-tier venue. The paper is technically sound and significant, but fails the novelty acceptance gate. Therefore, the original decision stands."
}

